<script>
 import {shortcutsSession,shortcutsAvailability} from './shortcuts-state.js';
 import {automatorLibrary,AUTOMATOR_MIME} from './automator-engine.js';
 import {shortcutsMenus} from './shortcuts-menus.js';
 import './shortcuts.css';
 let {state: shortcutsState,profile,windowId,window,files,applications,execute,registerView,available=true,active=true,controls}=$props();
 let root,scroller,error=$state(''),collection=$state('editor'),saveName=$state('My Shortcut'),inputIds=$state([]),variableName=$state('Files'),variableValue=$state('');
 let session=$derived(shortcutsSession(shortcutsState,windowId)),cap=$derived(shortcutsAvailability(profile)),busy=$derived(session?.status==='running');
 let sources=$derived(Array.isArray(files)&&Array.isArray(applications)),liveFiles=$derived(Array.isArray(files)?files.filter(f=>!f.deleted&&f.kind!=='application'):[]),folders=$derived(liveFiles.filter(f=>f.kind==='folder'));
 let documents=$derived(liveFiles.filter(f=>f.mime===AUTOMATOR_MIME||f.name.endsWith('.jworkflow')));
 let actions=$derived(automatorLibrary.filter(a=>(session?.category==='All'||a.category===session?.category)&&`${a.name} ${a.description}`.toLowerCase().includes(session?.search.toLowerCase()??'')));
 async function send(command,payload={}){if(typeof execute!=='function'){error='The registered Root command executor is unavailable.';return;}const r=await execute('shortcuts.'+command,{windowId},payload);error=r?.status==='applied'?'':r?.error?.message??'The command was not acknowledged.';return r;}
 function edit(action,key,value){return send('editAction',{action:{...action,params:{...action.params,[key]:value}}});}
 function fileToggle(action,id){const ids=action.params.fileIds;return edit(action,'fileIds',ids.includes(id)?ids.filter(v=>v!==id):[...ids,id]);}
 function drop(event,index){event.preventDefault();if(busy)return;const kind=event.dataTransfer.getData('application/x-jesteros-shortcuts-action');if(kind)send('addAction',{kind,index});}
 $effect(()=>{
  if(!root||!session||typeof registerView!=='function')return;
  const node=root,scrollNode=scroller,originalState=shortcutsState,originalSession=session,id=windowId;
  const mounted=()=>root===node&&node.isConnected&&shortcutsState===originalState&&shortcutsSession(shortcutsState,id)===originalSession&&available===true&&sources&&typeof execute==='function';
  const facade={available:mounted,setCollection(value,guard){if(guard?.()!==true||!mounted()||!['editor','library'].includes(value))return false;collection=value;return guard()===true&&mounted()&&collection===value;},setInput(ids,guard){if(guard?.()!==true||!mounted()||ids.some(id=>!liveFiles.some(f=>f.id===id)))return false;inputIds=[...ids];return guard()===true&&mounted();},focus(controlId,guard){if(guard?.()!==true||!mounted())return false;const el=Array.from(node.querySelectorAll('[data-control]')).find(n=>n.dataset.control===controlId);if(!el||el.disabled)return false;el.focus();return guard()===true&&mounted()&&document.activeElement===el;},scroll({top},guard){if(guard?.()!==true||!mounted()||scrollNode!==scroller||!scrollNode)return false;scrollNode.scrollTop=top;return guard()===true&&mounted();},describe(){return {appId:'shortcuts',windowId:id,available:mounted(),collection,inputIds:[...inputIds],controls:Array.from(node.querySelectorAll('[data-control]')).map(el=>({id:el.dataset.control,enabled:!el.disabled})),scrollTop:scrollNode?.scrollTop??0};}};
  registerView(id,facade);return ()=>registerView(id,null,facade);
 });
</script>
{#if session}
<section bind:this={root} class="shortcuts-app" class:editing={collection==='editor'} class:classic={/high-sierra|mojave/u.test(profile.id)} class:windows={profile.id.startsWith('windows11')} class:active aria-label={cap.label}>
 {#if profile.id.startsWith('windows11')}<nav class="shortcut-menus" aria-label="Shortcuts menus">{#each shortcutsMenus(shortcutsState,windowId) as menu}<details><summary>{menu.label}</summary><div>{#each menu.items as item}<button disabled={!item.enabled} onclick={()=>send(item.command.slice(10),item.payload)}>{item.label}</button>{/each}</div></details>{/each}</nav>{/if}
 <header class="shortcut-toolbar"><button data-control="collection" onclick={()=>send('collection',{collection:collection==='editor'?'library':'editor'})}>{collection==='editor'?'‹ All Shortcuts':'Edit Shortcut'}</button><button data-control="new" disabled={busy} title="New Shortcut" onclick={()=>send('new',{type:'workflow'})}>＋</button><button data-control="import" disabled={busy||!sources} onclick={()=>send('open')}>Import…</button><strong>{session.title}{session.dirty?' — Edited':''}</strong><button data-control="save" disabled={busy||!sources} onclick={()=>send('panel',{panel:'save'})}>Save…</button><button data-control="stop" aria-label="Stop Shortcut" disabled={!busy} onclick={()=>send('stop')}>■</button><button data-control="run" aria-label="Run Shortcut" disabled={busy||!sources||!session.actions.length} onclick={()=>send('run',{inputIds})}>▶</button></header>
 <div class="shortcut-layout">
 <aside class="shortcut-sidebar"><h2>Shortcuts</h2><button class:selected={collection==='editor'} onclick={()=>send('collection',{collection:'editor'})}>◈ Shortcut Editor</button><button class:selected={collection==='library'} onclick={()=>send('collection',{collection:'library'})}>▦ All Local Workflows <span>{documents.length}</span></button><div class="sidebar-caption">LOCAL COLLECTION</div><p>Portable workflows saved in scene Files. No iCloud, online Gallery or host automation.</p><button disabled={busy} onclick={()=>send('panel',{panel:'help'})}>? Shortcuts Help</button></aside>
 {#if collection==='library'}<main class="shortcut-collection"><h1>All Local Workflows</h1><p>Open an actual portable workflow in this editor. Save your current edits first.</p><div class="shortcut-grid">{#each documents as file,index}<article style={'--card-color:'+['#eb6b52','#d59b34','#48a782','#558cce'][index%4]}><span aria-hidden="true">◈</span><h2>{file.name}</h2><p>Portable .jworkflow</p><button disabled={busy||session.dirty} onclick={async()=>{const r=await send('open',{fileId:file.id});if(r?.status==='applied')await send('collection',{collection:'editor'});}}>Edit Workflow</button></article>{/each}</div>{#if !documents.length}<p>No workflows have been saved yet. Build a shortcut in the editor and choose Save.</p>{/if}</main>
 {:else}<main class="shortcut-editor"><div class="shortcut-input"><strong>Receive Files from Run input</strong><span>Get Specified Files overrides this input. Select one or more actual Files.</span><select data-control="run-input" multiple aria-label="Actual Files input for Run" disabled={busy||!sources} onchange={e=>send('input',{fileIds:Array.from(e.currentTarget.selectedOptions).map(o=>o.value)})}>{#each liveFiles as file}<option value={file.id} selected={inputIds.includes(file.id)}>{file.name}</option>{/each}</select></div><div bind:this={scroller} class="shortcut-actions" ondragover={e=>e.preventDefault()} ondrop={e=>drop(e,session.actions.length)} role="region" aria-label="Shortcut actions">
 {#if !session.actions.length}<div class="shortcut-empty"><div>◈</div><h1>Create a Shortcut</h1><p>Add actions from the right. Select Files, copy them, convert documents or resize genuine images, then inspect actual results.</p><button disabled={!sources} onclick={()=>send('addAction',{kind:'get-files'})}>Add Get Specified Files</button></div>{/if}
 {#each session.actions as action,index (action.id)}{@const entry=automatorLibrary.find(a=>a.kind===action.kind)}<article class="shortcut-action" class:selected={session.selected===action.id} class:disabled={!action.enabled} ondragover={e=>e.preventDefault()} ondrop={e=>{e.stopPropagation();drop(e,index);}}><header><button disabled={busy} onclick={()=>send('selectAction',{actionId:action.id})}>{entry.name}</button><label title="Enable action"><input type="checkbox" disabled={busy} checked={action.enabled} onchange={e=>send('editAction',{action:{...action,enabled:e.currentTarget.checked}})}/></label><button aria-label="Move up" disabled={busy||index===0} onclick={()=>send('moveAction',{actionId:action.id,index:index-1})}>↑</button><button aria-label="Move down" disabled={busy||index===session.actions.length-1} onclick={()=>send('moveAction',{actionId:action.id,index:index+1})}>↓</button><button aria-label="Remove action" disabled={busy} onclick={()=>send('deleteAction',{actionId:action.id})}>×</button></header><div class="shortcut-parameters">
 {#if action.kind==='get-files'}{#each action.params.fileIds as id}<div class="file-token">{liveFiles.find(f=>f.id===id)?.name??'Unavailable File: '+id}<button disabled={busy} aria-label="Remove File" onclick={()=>fileToggle(action,id)}>×</button></div>{/each}<select data-control={'files-'+action.id} disabled={busy||!sources} value="" onchange={e=>{if(e.currentTarget.value)fileToggle(action,e.currentTarget.value);e.currentTarget.value='';}}><option value="">Add actual Files…</option>{#each liveFiles.filter(f=>!action.params.fileIds.includes(f.id)) as file}<option value={file.id}>{file.name}</option>{/each}</select>
 {:else if action.kind==='rename-files'}<label>Rename using<select disabled={busy} value={action.params.mode} onchange={e=>edit(action,'mode',e.currentTarget.value)}><option value="prefix">Add Text</option><option value="replace">Replace Text</option><option value="sequence">Sequential Numbers</option></select></label>{#if action.params.mode==='replace'}<label>Find<input maxlength="128" disabled={busy} value={action.params.find} onchange={e=>edit(action,'find',e.currentTarget.value)}/></label>{/if}<label>Text<input maxlength="128" disabled={busy} value={action.params.text} onchange={e=>edit(action,'text',e.currentTarget.value)}/></label>{#if action.params.mode==='sequence'}<label>Start at<input type="number" min="1" max="999999" disabled={busy} value={action.params.start} onchange={e=>edit(action,'start',Number(e.currentTarget.value))}/></label>{/if}
 {:else if ['copy-files','scale-images','convert-documents'].includes(action.kind)}<label>Destination<select disabled={busy||!sources} value={action.params.parentId} onchange={e=>edit(action,'parentId',e.currentTarget.value)}>{#each folders as folder}<option value={folder.id}>{folder.name}</option>{/each}</select></label><label>Filename suffix<input maxlength="64" disabled={busy} value={action.params.suffix} onchange={e=>edit(action,'suffix',e.currentTarget.value)}/></label>{#if action.kind==='scale-images'}<label>Width in pixels<input type="number" min="1" max="4096" disabled={busy} value={action.params.width} onchange={e=>edit(action,'width',Number(e.currentTarget.value))}/></label><label>Rotation<select disabled={busy} value={action.params.rotation} onchange={e=>edit(action,'rotation',Number(e.currentTarget.value))}>{#each [0,90,180,270] as n}<option value={n}>{n}°</option>{/each}</select></label><label>Encode<select disabled={busy} value={action.params.format} onchange={e=>edit(action,'format',e.currentTarget.value)}>{#each ['png','jpeg','webp'] as format}<option value={format}>{format.toUpperCase()}</option>{/each}</select></label>{:else if action.kind==='convert-documents'}<label>Format<select disabled={busy} value={action.params.format} onchange={e=>edit(action,'format',e.currentTarget.value)}><option value="txt">Plain Text</option><option value="rtf">Rich Text Format</option></select></label><label>Append text<textarea maxlength="4096" disabled={busy} value={action.params.append} onchange={e=>edit(action,'append',e.currentTarget.value)}></textarea></label>{/if}
 {:else if action.kind==='open-app'||action.kind==='quit-app'}<label>Application<select disabled={busy||!sources} value={action.params.appId} onchange={e=>edit(action,'appId',e.currentTarget.value)}>{#each applications??[] as app}<option value={app.id??app.appId}>{app.name??app.label??app.id??app.appId}</option>{/each}</select></label><p>Runs the registered Root command. Unsaved document decisions are preserved.</p>
 {:else if action.kind==='set-variable'||action.kind==='get-variable'}<label>Variable<select disabled={busy} value={action.params.name} onchange={e=>edit(action,'name',e.currentTarget.value)}><option value={action.params.name}>{action.params.name}</option>{#each session.variables.filter(v=>v.name!==action.params.name) as variable}<option value={variable.name}>{variable.name}</option>{/each}</select></label><p>Set retains file references for this run. Get restores them.</p>
 {:else}<p>Display the names and MIME types of the actual current output Files.</p>{/if}
 </div></article>{/each}</div>
 {#if shortcutsState.preferences.showVariables}<section class="shortcut-variables"><h3>Variables</h3><p>Use ${'{Name}'} in text fields. Set/Get actions store Files within this run.</p>{#each session.variables as variable}<div><input aria-label="Variable name" maxlength="64" disabled={busy} value={variable.name} onchange={e=>send('setVariable',{variable:{...variable,name:e.currentTarget.value}})}/><input aria-label="Variable value" maxlength="4096" disabled={busy} value={variable.value} onchange={e=>send('setVariable',{variable:{...variable,value:e.currentTarget.value}})}/><button disabled={busy} onclick={()=>send('deleteVariable',{variableId:variable.id})}>Delete</button></div>{/each}<div><input aria-label="New variable name" bind:value={variableName} maxlength="64"/><input aria-label="New variable value" bind:value={variableValue} maxlength="4096"/><button disabled={busy} onclick={()=>send('setVariable',{variable:{id:'shortcuts-variable-'+shortcutsState.nextId,name:variableName,value:variableValue}})}>Add</button></div></section>{/if}
 {#if shortcutsState.preferences.showLog}<section class="shortcut-results"><header><strong>Results · {session.status}</strong><button disabled={busy} onclick={()=>send('clearLog')}>Clear</button></header>{#each session.results as result}<div><strong>{result.name}</strong> <small>{result.mime||result.summary}</small><code>{result.fileId}</code></div>{/each}<ol>{#each session.log as row}<li class:error={row.level==='error'}><time>{new Date(row.time).toISOString().slice(11,19)}</time> {row.message}</li>{/each}</ol></section>{/if}
 </main>{#if shortcutsState.preferences.showLibrary}<aside class="shortcut-library"><input data-control="search" type="search" placeholder="Search Actions" maxlength="128" disabled={busy} value={session.search} oninput={e=>send('search',{query:e.currentTarget.value})}/><select aria-label="Action category" disabled={busy} value={session.category} onchange={e=>send('search',{query:session.search,category:e.currentTarget.value})}>{#each ['All','Files & Folders','Photos','Text','Utilities'] as category}<option value={category}>{category}</option>{/each}</select><h3>Actions</h3>{#each actions as action}<button draggable={!busy} disabled={busy} ondragstart={e=>e.dataTransfer.setData('application/x-jesteros-shortcuts-action',action.kind)} onclick={()=>send('addAction',{kind:action.kind})}><strong>{action.name}</strong><small>{action.description}</small></button>{/each}</aside>{/if}{/if}
 </div><footer class="shortcut-status"><span>{session.actions.length} actions · {session.status}</span><span>{cap.disclosure}</span></footer>
 {#if !sources}<div role="alert" class="shortcut-error">The actual Root Files and application inventory are required; no substitute sources are created.</div>{/if}{#if error}<div role="alert" class="shortcut-error">{error}<button aria-label="Dismiss" onclick={()=>error=''}>×</button></div>{/if}
 {#if session.panel!=='none'}<div class="shortcut-shade"><section class="shortcut-sheet" role="dialog" aria-modal="true" aria-label="Shortcuts dialog">
 {#if session.panel==='save'}<h2>Save Portable Workflow</h2><label>Name<input data-control="save-name" bind:value={saveName} maxlength="240"/></label><p>Saved as a genuine JSON .jworkflow document in scene Files. Apple's signed proprietary .shortcut format is not supported.</p><button onclick={()=>send('panel',{panel:'none'})}>Cancel</button><button onclick={()=>send('save',{name:saveName,saveAs:true})}>Save</button>
 {:else if session.panel==='close'}<h2>Save changes to {session.title}?</h2><button onclick={()=>send('closeDecision',{decision:'discard'})}>Don’t Save</button><button onclick={()=>send('closeDecision',{decision:'cancel'})}>Cancel</button><button onclick={()=>send('closeDecision',{decision:'save'})}>Save</button>
 {:else if session.panel==='preferences'}<h2>Shortcuts Settings</h2>{#each [['showLibrary','Show Action Library'],['showVariables','Show Variables'],['showLog','Show Results and Log'],['confirmRun','Confirm before running']] as [key,label]}<label><input type="checkbox" checked={shortcutsState.preferences[key]} disabled={busy} onchange={e=>send('preferences',{values:{...shortcutsState.preferences,[key]:e.currentTarget.checked}})}/>{label}</label>{/each}<button onclick={()=>send('panel',{panel:'none'})}>Done</button>
 {:else if session.panel==='run-confirm'}<h2>Run this shortcut?</h2><p>Files effects are atomic per segment. Earlier committed segments and app effects remain if a later action fails. Stop discards only pending effects.</p><button onclick={()=>send('panel',{panel:'none'})}>Cancel</button><button onclick={()=>send('run',{inputIds,confirmed:true})}>Run</button>
 {:else if session.panel==='new'}<h2>Create a Shortcut</h2><p>Start a new bounded portable workflow.</p><button onclick={()=>send('panel',{panel:'none'})}>Cancel</button><button onclick={()=>send('new',{type:'workflow'})}>Create</button>
 {:else}<h2>Build a useful shortcut</h2><ol><li>Add Get Specified Finder Items and choose a real File, or select Run Input in the left sidebar.</li><li>Add Copy Finder Items to preserve the original, then choose a destination and filename suffix.</li><li>Add Convert Text Documents for genuine TXT/RTF, or Scale and Rotate Images for genuine PNG/JPEG/WebP.</li><li>Add View Results, click Run and inspect published File IDs and the truthful log.</li></ol><p>Variables substitute text with ${'{Name}'}. Set/Get Variable preserves Files references during one run. Enable or reorder actions with each action’s controls. A failed Files segment publishes none of its staged changes.</p><p>{cap.disclosure}</p><p>Official guide: support.apple.com/guide/shortcuts-mac/create-a-custom-shortcut-apd84c576f8c/7.0/mac/14.0</p><button onclick={()=>send('panel',{panel:'none'})}>Done</button>{/if}
 </section></div>{/if}
</section>{/if}
